async function finishOriginal(){if(!originalContext||originalContext.meta.completed)return;const c=originalContext,p=data.profiles[profile];c.meta.completed=true;queueReward(c.meta.ledger,'stage',25,50,'stage:'+c.stage);bankRun(p,c.meta.ledger,data.packs[c.packId]);save();await closeOriginal();screen(`<section class="panel"><p class="eyebrow">STAGE COMPLETE</p><div class="treasure">🏆</div><h2>${esc(THEMES[c.world].stages[c.stage])}</h2><p>Your crystals, learning and destination badge are saved.</p><div class="row"><button class="primary" id="original-next">${c.stage<2?'Next Stage':'Adventure Map'} ➜</button><button id="original-map">Adventure Map</button><button id="original-menu">Back to Games</button></div></section>`,'original-stage');on('original-next',()=>c.stage<2?beginGameplay('original',c.world,c.stage+1):showMap('original',c.world));on('original-map',()=>showMap('original',c.world));on('original-menu',()=>playerMenu());}
