function startNew(stage=0){if(!Number.isInteger(stage))stage=0;const p=data.profiles[profile];run=newRun(profile,p.selectedLevel||p.activePack,{...p.settings,theme:p.theme});run.stage=stage;run.gameMode='runner';p.lastAdventure={mode:'runner',world:p.theme,stage,packId:run.packId};run.sessionId=new Date().toISOString()+'-'+Math.random().toString(36).slice(2,7);attachPet();p.sessions++;p.lastSession=run.sessionId;const h=history(data,profile,run.packId);h.sessions=(h.sessions||0)+1;h.lastSession=run.sessionId;p.runs[run.packId]=run;syncRun();play();notice(profile==='kal'?'Beep: Follow the crystals! Swipe or use the big buttons.':'Follow the crystals. Watch for JUMP, SLIDE and DODGE.');}
