function hud(){if(!run)return;updateMagicHud(run);updateJumpHint();$('hearts').textContent=Array.from({length:3},(_,i)=>i<run.hearts?'♥':'♡').join(' ');$('crystals').textContent='◆ '+run.crystals;$('stage-name').textContent=`${run.stage+1}/3 • ${THEMES[run.theme].stages[run.stage]}`;$('checkpoint-progress').textContent=run.finishDistance?'FINISH LINE AHEAD!':`${run.sinceGate}/${run.settings.interval} safe groups • gate ${run.stageGates+1}/4`;$('gate-meter').style.width=(run.finishDistance?100:run.sinceGate/run.settings.interval*100)+'%';$('audio').textContent=data.sound?'♪ ON':'♪ OFF';for(const kind of ['shield','dash','blast']){const b=document.querySelector(`[data-select="${kind}"]`);b.textContent=(kind==='dash'?'SMASH DASH':kind.toUpperCase())+' '+run.stock[kind];b.classList.toggle('selected',run.selectedPower===kind);}$('active-power').textContent=run.active?`${run.active.kind.toUpperCase()} ${Math.ceil(run.active.left)}s`:'12 crystals charge a power';}
function updateJumpHint(){const hint=$('obstacle-hint');if(!hint)return;const speed=run.settings.speed*(1+run.stage*.08)*(run.active?.kind==='dash'?1.35:1);const upcoming=run.groups.filter(g=>!g.passed&&g.distance>=run.distance).map(g=>({g,o:g.obstacles.find(o=>!o.broken&&Math.abs(o.lane-run.player.x)<.55)})).find(x=>x.o);if(!upcoming||run.player.y>.3||(upcoming.g.distance-run.distance)/speed>(run.petAbility==='scout'?3.5:2.5)){hint.hidden=true;return;}const eta=(upcoming.g.distance-run.distance)/speed,type=upcoming.o.type;hint.hidden=false;hint.textContent=type==='high'?(run.player.slide>0?'STAY LOW ↓':eta<1.5?'SLIDE NOW ↓':'HOLD SLIDE ↓ FOR THIS BEAM'):eta<1.05?'JUMP NOW ↑':type==='full'?'BIG ROCK: GET READY TO JUMP OR DODGE':'GET READY TO JUMP ↑';}
const controls=bindRunnerControls({surface:$('scene'),buttons:$('controls'),isRunning:()=>appMode==='play'&&run?.mode==='running',onSlideHold:held=>{if(run)holdSlide(run,held);},onAction:action=>{if(!run)return;if(action==='left')move(run,-1);if(action==='right')move(run,1);if(action==='jump')jump(run);if(action==='slide')slide(run);if(action==='power'&&!activate(run))notice('Collect a power gem or 12 crystals to charge this power.');}});
