function questionArt(q){if(q.picture==='layers')return '<svg viewBox="0 0 450 100" role="img" aria-label="Undisturbed rock layers, top above middle above bottom"><rect x="50" y="2" width="350" height="29" fill="#d7ba86"/><rect x="50" y="35" width="350" height="29" fill="#c89279"/><rect x="50" y="68" width="350" height="29" fill="#9a8dba"/><g fill="#152c40" text-anchor="middle" font-size="19"><text x="225" y="24">TOP</text><text x="225" y="57">MIDDLE</text><text x="225" y="90">BOTTOM</text></g></svg>';if(q.picture==='north')return dipperSvg(true,true);if(q.picture==='dipper')return dipperSvg();if(q.picture==='directions')return demoMarkup('rise',q.concepts.includes('west')?1:0);const demos={spin:'spin',daystars:'daystars',daynight:'light',directions:'rise',clock:'clock',orbit:'orbit',moonOrbit:'moonOrbit',phases:'phases'};return demos[q.picture]?demoMarkup(demos[q.picture],1):'';}
