function frame(now){if(stopped)return;const frameCost=now-last,elapsed=Math.min(.05,Math.max(0,frameCost/1000));last=now;view.adaptResolution(frameCost,appMode==='play'&&!reducedMotion);controls.update(elapsed);if(appMode==='play'&&run){let remaining=elapsed;while(remaining>0&&run.mode==='running'){const dt=Math.min(remaining,1/120);remaining-=dt;const events=step(run,dt);for(const event of events){if(['crystal','jump','hurt','power','smash'].includes(event.type))sfx(event.type);if(event.type==='crystal'){run.petFlash=run.time+.5;try{$('crystals').animate([{transform:'scale(1.13)'},{transform:'scale(1)'}],{duration:180});}catch{}if(run.streak>0&&run.streak%12===0)notice('Crystal streak '+run.streak+'!');}if(event.type==='pickup')notice(event.kind.toUpperCase()+' charged! Tap its name, then POWER.');if(event.type==='protected')notice('Shield saved a heart!');if(['gate','hearts','explore'].includes(event.type)){beginChallenge(event.type);break;}if(event.type==='stage'){stageFinish();break;}}}hud();saveClock+=elapsed;if(saveClock>2){syncRun();saveClock=0;}}if(now-lastDraw>=(appMode==='play'?(reducedMotion?33:16):66)){if(!classicFrame&&!appMode.startsWith('reading')&&appMode!=='accounts')view.render(run||preview,now/1000);lastDraw=now;}if(now>noticeTime)$('notice').classList.remove('visible');frameId=requestAnimationFrame(frame);}
window.addEventListener('resize',()=>{view.resize();if(innerHeight>innerWidth)pause();});window.addEventListener('blur',()=>{controls.clear();cancelVoice();pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden){controls.clear();cancelVoice();pause();syncRun();}});window.addEventListener('pagehide',e=>{try{classicFrame?.contentWindow.arcadeLifecycle?.dispose();}catch{}stash();cancelVoice();controls.clear();if(!e.persisted){stopped=true;cancelAnimationFrame(frameId);controls.destroy();sound.close();view.dispose();}});document.addEventListener('contextmenu',e=>e.preventDefault());window.addEventListener('keydown',e=>{if(e.key==='Escape')pause();});$('scene').addEventListener('webglcontextlost',e=>{e.preventDefault();pause();notice('Graphics paused. Reload to restore your saved adventure.');});
